import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class TreeCounts {
    static Map<Integer, Integer> dp1 = new HashMap<>();
    static Map<String, Integer> dp2 = new HashMap<>();

    public static int computeTreeCounts(int n) {
        if (n < 0) {
            return 0;
        }
        if (n < 2) {
            return 1;
        }
        if (!dp1.containsKey(n)) {
            int total = 0;
            for (int i = 0; i < n; i++) {
                total += computeTreeCounts(i) * computeTreeCounts(n - 1 - i);
            }
            dp1.put(n, total);
        }
        return dp1.get(n);
    }

    public static int computeSubtreeCounts(int n, int h) {
        if (n < 0 || h <= 0 || n >= Math.pow(2, h - 1)) {
            return 0;
        }
        if (n < 2) {
            return 1;
        }
        if (n < h) {
            return computeTreeCounts(n);
        }
        String key = n + "," + h;
        if (!dp2.containsKey(key)) {
            int total = 0;
            for (int i = 0; i < n; i++) {
                total += computeSubtreeCounts(i, h - 1) * computeSubtreeCounts(n - 1 - i, h - 1);
            }
            dp2.put(key, total);
        }
        return dp2.get(key);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int A = scanner.nextInt();
        int B = scanner.nextInt();
        System.out.println(computeTreeCounts(A) - computeSubtreeCounts(A, B));
        scanner.close();
    }
}
